<?php declare(strict_types=1); ?>
<header class="resource-header"><div><span class="booking-eyebrow">Danh mục dùng chung</span><h1>Tiện nghi</h1><p>Mã và phạm vi được cố định sau khi tạo; bản ghi đang dùng nên chuyển sang ngừng thay vì xóa.</p></div></header>
<section class="admin-split-layout"><article class="resource-card admin-form-card"><h2>Tạo tiện nghi</h2><form class="booking-edit-form" method="post" action="<?= $baseUrl ?>/admin/facilities"><input type="hidden" name="_token" value="<?= $csrfToken ?>"><label class="field"><span>Mã tiện nghi</span><input name="code" maxlength="40" pattern="[A-Z0-9_]{2,40}" required></label><label class="field"><span>Tên hiển thị</span><input name="name" maxlength="120" required></label><label class="field"><span>Phạm vi</span><select name="scope"><option value="PROPERTY">Cơ sở</option><option value="ROOM">Loại phòng</option></select></label><input type="hidden" name="status" value="HOAT_DONG"><button class="button button--primary" type="submit">Tạo tiện nghi</button></form></article>
<article class="resource-surface"><form class="resource-toolbar" method="get" action="<?= $baseUrl ?>/admin/facilities"><label class="toolbar-select"><span class="visually-hidden">Phạm vi</span><select name="scope"><option value="">Mọi phạm vi</option><option value="PROPERTY"<?= $scopeFilter==='PROPERTY'?' selected':'' ?>>Cơ sở</option><option value="ROOM"<?= $scopeFilter==='ROOM'?' selected':'' ?>>Loại phòng</option></select></label><label class="toolbar-select"><span class="visually-hidden">Trạng thái</span><select name="status"><option value="">Mọi trạng thái</option><option value="HOAT_DONG"<?= $statusFilter==='HOAT_DONG'?' selected':'' ?>>Hoạt động</option><option value="NGUNG"<?= $statusFilter==='NGUNG'?' selected':'' ?>>Ngừng</option></select></label><button class="button button--secondary button--small">Lọc</button></form><div class="admin-facility-list"><?php foreach ($facilities as $facility): ?><form method="post" action="<?= $baseUrl ?>/admin/facilities/<?= (int)$facility['id'] ?>/update"><input type="hidden" name="_token" value="<?= $csrfToken ?>"><div><strong><?= $facility['code'] ?></strong><small><?= $facility['scope']==='PROPERTY'?'Cơ sở':'Loại phòng' ?> · đang dùng <?= (int)$facility['usageCount'] ?> nơi</small></div><label class="field"><span>Tên</span><input name="name" value="<?= $facility['name'] ?>" maxlength="120" required></label><label class="field"><span>Trạng thái</span><select name="status"><option value="HOAT_DONG"<?= $facility['status']==='HOAT_DONG'?' selected':'' ?>>Hoạt động</option><option value="NGUNG"<?= $facility['status']==='NGUNG'?' selected':'' ?>>Ngừng</option></select></label><button class="button button--secondary button--small" type="submit">Lưu</button></form><?php endforeach; ?></div></article></section>
